template<class T>
void STLClearObject(T* obj) {
  T tmp;
  tmp.swap(*obj);


  obj->reserve(0);
}


template <typename ResultType, typename Arg1, typename Arg2>
ResultType STLSetDifference(const Arg1& a1, const Arg2& a2) {
  true ? (void)0 : ::logging::VoidifyStream(!(ranges::is_sorted(a1))) & (*::logging::g_swallow_stream);
  true ? (void)0 : ::logging::VoidifyStream(!(ranges::is_sorted(a2))) & (*::logging::g_swallow_stream);
  ResultType difference;
  std::set_difference(a1.begin(), a1.end(),
                      a2.begin(), a2.end(),
                      std::inserter(difference, difference.end()));
  return difference;
}


