constexpr bool operator==(const AXMode& lhs, const AXMode& rhs) {
  return lhs.flags() == rhs.flags() &&
         lhs.experimental_flags() == rhs.experimental_flags();
}

constexpr bool operator!=(const AXMode& lhs, const AXMode& rhs) {
  return lhs.flags() != rhs.flags() ||
         lhs.experimental_flags() != rhs.experimental_flags();
}

constexpr AXMode operator|(const AXMode& lhs, const AXMode& rhs) {
  return {lhs.flags() | rhs.flags(),
          lhs.experimental_flags() | rhs.experimental_flags()};
}

constexpr AXMode operator&(const AXMode& lhs, const AXMode& rhs) {
  return {lhs.flags() & rhs.flags(),
          lhs.experimental_flags() & rhs.experimental_flags()};
}



