  RawValueType raw_value() const { return raw_value_; }


  ObjectType* Get() const;


  bool operator==(const Handle& other) const {
    return raw_value_ == other.raw_value_;
  }
  bool operator!=(const Handle& other) const {
    return raw_value_ != other.raw_value_;
  }
  bool operator<(const Handle& other) const {
    return raw_value_ < other.raw_value_;
  }


  static constexpr RawValueType NullValue = 0;
